async function api(action,data={}){return (await call({action,...data})).data}
async function run(fn){if(busy)return;busy=true;try{await fn()}catch(e){message(e.message||'İşlem tamamlanamadı.')}finally{busy=false}}
const clone=x=>JSON.parse(JSON.stringify(x));
