function field(parent,label,path,type='text',opts={}){const wrapper=el('label',label),input=el(type==='textarea'?'textarea':type==='select'?'select':'input');if(type!=='textarea'&&type!=='select')input.type=type;input.dataset.field=path;const value=path.split('.').reduce((o,k)=>o?.[k],record);if(type==='select')for(const [id,title]of opts.options||[]) {const o=el('option',title);o.value=id;input.appendChild(o)}input.value=opts.stringify?opts.stringify(value):value??'';if(type==='textarea')input.rows=opts.rows||3;if(opts.max)input.maxLength=opts.max;if(opts.min!==undefined)input.min=opts.min;if(opts.maxValue!==undefined)input.max=opts.maxValue;input.onchange=()=>{try{set(path,opts.parse?opts.parse(input.value):type==='number'?Number(input.value):input.value)}catch(e){message(e.message)}};wrapper.appendChild(input);parent.appendChild(wrapper);return input}
function updateState(){const found=items.find(x=>x.id===record?.id);$('editState').textContent=(states[found?.status]||'Yeni taslak')+' · '+(dirty()?'Kaydedilmemiş değişiklikler':'Kaydedildi');$('editHeading').textContent=record?.title||'Yeni içerik';$('undo').disabled=!undoStack.length||uploading;$('save').disabled=uploading;$('publish').disabled=uploading;$('duplicate').disabled=uploading;if(lastSavedAt&&!dirty())$('editState').textContent+=' · Son kayıt '+new Date(lastSavedAt).toLocaleTimeString('tr-TR',{hour:'2-digit',minute:'2-digit'});if(contentKinds.includes(record?.kind))$('publish').textContent=step===3?'Yayınla':'Önizle ve yayınla';}
async function reload(){items=(await api('list')).items;renderList();renderRecent()}
function renderRecent(){$('recent').replaceChildren();for(const item of items.slice(0,6))$('recent').appendChild(itemRow(item));if(!items.length)$('recent').appendChild(el('p','Henüz içerik yok. Bir modül seç veya mevcut içerikleri içe al.'))}
function show(view){for(const id of ['home','library','editor'])$(id).hidden=id!==view}
function leave(){if(!document.getElementById('gameStudio').hidden&&!gameStudio.canLeave())return false;if(uploading){message('Dosya yüklemesi sürüyor. Tamamlandıktan sonra ayrılabilirsin.');return false;}return !dirty()||confirm('Kaydedilmemiş değişikliklerin var. Ayrılmak istiyor musun?')}
