function itemRow(item){const row=el('div',undefined,'item'),copy=el('div',undefined,'copy');copy.append(el('b',item.draft.title),el('small',(labels[item.draft.kind]||'')+' · '+(window.LinguAudience.grades(item.draft).length?window.LinguAudience.grades(item.draft).join(', ')+'. sınıf':'Tüm sınıflar')+' · '+window.LinguAudience.label(item.draft,'admin')+' · '+item.draft.unit));row.append(copy,el('span',states[item.status],'status'),button('Düzenle',()=>open(item)));return row}
function renderList(){const box=$('items');box.replaceChildren();const query=$('search').value.toLocaleLowerCase('tr'),status=$('statusFilter').value,grade=$('gradeFilter').value;const filtered=items.filter(x=>(kind==='content'?['video','song','activity','question'].includes(x.draft.kind):x.draft.kind===kind)&&(kind!=='content'||$('kindFilter').value==='all'||x.draft.kind===$('kindFilter').value)&&(status==='all'||x.status===status)&&(grade==='all'||(!window.LinguAudience.grades(x.draft).length||window.LinguAudience.grades(x.draft).includes(Number(grade))))&&JSON.stringify(x.draft).toLocaleLowerCase('tr').includes(query)).sort((a,b)=>a.draft.order-b.draft.order);for(const [i,item]of filtered.entries()){const row=itemRow(item);row.draggable=true;row.dataset.id=item.id;row.ondragstart=e=>e.dataTransfer.setData('text/plain',item.id);row.ondragover=e=>e.preventDefault();row.ondrop=e=>{e.preventDefault();run(()=>reorder(e.dataTransfer.getData('text/plain'),item.id))};for(const [label,offset]of [['↑',-1],['↓',1]]){const b=button(label,()=>{const target=filtered[i+offset];if(target)return reorder(item.id,target.id)});b.setAttribute('aria-label',item.draft.title+' '+(offset<0?'yukarı':'aşağı'));b.disabled=!filtered[i+offset];row.appendChild(b)}box.appendChild(row)}if(!filtered.length)box.appendChild(el('p','Bu filtrelerle içerik bulunamadı.'))}
async function reorder(id,target){const sorted=items.filter(x=>kind==='content'?['video','song','activity','question'].includes(x.draft.kind):x.draft.kind===kind).sort((a,b)=>a.draft.order-b.draft.order),from=sorted.findIndex(x=>x.id===id),to=sorted.findIndex(x=>x.id===target);if(from<0||to<0)return;const [moved]=sorted.splice(from,1);sorted.splice(to,0,moved);for(const [order,item]of sorted.entries())if(item.draft.order!==order)await api('save',{record:{...item.draft,order},revision:item.revision});await reload();message('Sıralama taslağa kaydedildi. Yayındaki sıralamayı değiştirmek için ilgili içerikleri yayınla.')}
