 parent.append(el('h2','Öğrenciye yayınlamadan önce'),el('p',record.title||'Başlık henüz yazılmadı'),el('p','Tür: '+({song:'Şarkı',video:'Hikâye',activity:'Oyun'}[record.kind])+' · '+record.payload.questions.length+' soru','muted'));
