 if(path==='source'&&!/^video\/(mp4|webm)$/.test(file.type)&&!(record.kind==='song'&&/^audio\/(mpeg|ogg|wav|mp4)$/.test(file.type)))throw Error('Bu içerik türüne uygun bir medya dosyası seç.');
