 const owner=record,id='media-'+crypto.randomUUID().slice(0,12),storagePath='media/'+id+'/'+crypto.randomUUID()+'.'+(file.name.split('.').at(-1)||'bin'),status=document.querySelector('[data-transfer="'+path+'"]');uploading=true;updateState();
