  const media={...newRecord('media'),id,title:file.name,source:'https://firebasestorage.googleapis.com/v0/b/'+firebaseConfig.storageBucket+'/o/'+encodeURIComponent(storagePath)+'?alt=media',storagePath,mime:file.type,size:file.size};
