async function save(){const clean=S.validate(record);await api('save',{record:clean,revision});record=clean;await reload();revision=items.find(x=>x.id===record.id).revision;baseline=JSON.stringify(record);lastSavedAt=Date.now();updateState();message('Taslak kaydedildi. Öğrenci ekranı değişmedi.')}
async function publish(){
 if(uploading)throw Error('Önce dosya yüklemesinin tamamlanmasını bekle.');
 if(contentKinds.includes(record.kind)&&step!==3){step=3;renderEditor();return;}
 const issues=publicationIssues(record,items,S);if(issues.length){step=3;renderEditor();message('Yayınlamadan önce listelenen eksikleri tamamla.');return;}
 S.validate(record,true);
 const dependencies=items.filter(x=>record.links.includes(x.id)&&x.draft.kind==='media'&&!x.published);
 if(!confirm('“'+record.title+'” öğrencilere yayınlansın mı?'+(dependencies.length?'\nBu içeriğin '+dependencies.length+' yeni medya dosyası da erişime açılacak.':'')))return;
 if(dirty()||!revision)await save();
 for(const item of dependencies)await api('publish',{id:item.id,revision:item.revision});
 await api('publish',{id:record.id,revision});await reload();revision=items.find(x=>x.id===record.id).revision;baseline=JSON.stringify(record);updateState();message('İçerik yayınlandı. LinguCat sonraki açılışta yeni kataloğu alır.');
}

