const mediaBlobs=new Map();async function preview(questionId,scene=false){if(questionId)document.querySelector('.preview').hidden=false;const payload=previewRecord();if(payload.record||payload.appearance){for(const media of items.filter(x=>x.draft.kind==='media'&&x.draft.storagePath&&!x.published)){const m=media.draft;if(JSON.stringify(payload).includes(m.source)){if(!mediaBlobs.has(m.storagePath))mediaBlobs.set(m.storagePath,URL.createObjectURL(await getBlob(ref(storage,m.storagePath))));const local=mediaBlobs.get(m.storagePath);if(payload.record)payload.record=JSON.parse(JSON.stringify(payload.record).split(m.source).join(local));if(payload.appearance)payload.appearance=JSON.parse(JSON.stringify(payload.appearance).split(m.source).join(local));}}}if(questionId)payload.questionId=questionId;if(scene){const q=record.kind==='question'?record.payload:record.payload.questions.find(q=>q.id===questionId);payload.scene=q.scene}const itemsForPreview=items.filter(x=>x.published).map(x=>x.published);frame.contentWindow?.postMessage({type:'linguadmin:preview',token:previewToken,items:itemsForPreview,audience:{role:$('previewRole').value,grade:Number($('previewGrade').value)},...payload},location.origin);$('previewState').textContent=frameReady?'Önizleme güncelleniyor…':'Gerçek LinguCat yükleniyor…'}
let previewTimer;function schedulePreview(){clearTimeout(previewTimer);previewTimer=setTimeout(()=>{if(frameReady&&record)preview().catch(e=>{$('previewState').textContent=e.message})},200)}
window.addEventListener('message',e=>{if(e.source!==frame.contentWindow||e.origin!==location.origin||e.data?.token!==previewToken)return;if(e.data.type==='linguadmin:preview-ready'){frameReady=true;schedulePreview()}if(e.data.type==='linguadmin:preview-applied')$('previewState').textContent='Gerçek LinguCat görünümü hazır.';if(e.data.type==='linguadmin:preview-error')$('previewState').textContent=e.data.message});
function resizePreview(){const [w,h]=$('viewport').value.split(',').map(Number),host=$('frameHost'),scale=Math.min(host.clientWidth/w,host.clientHeight/h);frame.style.width=w+'px';frame.style.height=h+'px';frame.style.transform='scale('+scale+')';frame.style.left=Math.max(0,(host.clientWidth-w*scale)/2)+'px'}
new ResizeObserver(resizePreview).observe($('frameHost'));$('viewport').onchange=resizePreview;
function download(name,value){const url=URL.createObjectURL(new Blob([JSON.stringify(value,null,2)],{type:'application/json'})),a=el('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)}
async function importFile(file){if(file.size>1024*1024)throw Error('JSON 1 MB sınırını aştı.');const raw=JSON.parse((await file.text()).replace(/^\uFEFF/,''));let candidates=Array.isArray(raw)?raw:raw.items||[raw];candidates=candidates.map(v=>{if(v.draft)return v.draft;if(v.schemaVersion===1)return {...newRecord('video'),id:v.id,title:v.title,description:v.description,payload:v};if(v.prompt&&v.options)return {...newRecord('question'),id:v.id,title:v.prompt.slice(0,120),payload:v};return v});const validated=candidates.map(v=>S.validate(v));if(new Set(validated.map(v=>v.id)).size!==validated.length)throw Error('İçe aktarmada yinelenen kimlik var.');if(!confirm(validated.length+' içerik taslak olarak kaydedilsin mi? Aynı kimlikteki taslak güncellenir; yayın değişmez.'))return;for(const r of validated){const old=items.find(x=>x.id===r.id);await api('save',{record:r,revision:old?.revision||0})}await reload();message(validated.length+' taslak içe aktarıldı.')}
$('jsonFile').onchange=()=>run(async()=>{try{await importFile($('jsonFile').files[0])}finally{$('jsonFile').value=''}});
$('import').onclick=()=>$('jsonFile').click();$('exportAll').onclick=()=>download('linguadmin-'+kind+'.json',items.filter(x=>kind==='content'?['video','song','activity','question'].includes(x.draft.kind):x.draft.kind===kind).map(x=>x.draft));$('exportOne').onclick=()=>download(record.id+'.json',record);
$('new').onclick=()=>{if(kind==='content'){chooseType();return;}if(!leave())return;record=newRecord();revision=0;baseline='';undoStack=[];show('editor');renderEditor()};$('back').onclick=()=>go(kind);
$('save').onclick=()=>run(save);$('publish').onclick=()=>run(publish);$('preview').onclick=()=>run(()=>preview());$('undo').onclick=()=>{if(undoStack.length){record=undoStack.pop();renderEditor()}};
$('duplicate').onclick=()=>{remember();record={...clone(record),id:'copy-'+crypto.randomUUID().slice(0,8),title:record.title+' · Kopya'};if(record.payload.schemaVersion)record.payload.id=record.id;revision=0;baseline='';renderEditor()};
$('archive').onclick=()=>run(async()=>{if(!revision)throw Error('Önce taslağı kaydet.');if(!confirm('İçerik arşivlensin mi? Bağlı içeriklerde kullanılıyorsa işlem engellenir; dosya kalıcı silinmez.'))return;await api('archive',{id:record.id,revision});baseline=JSON.stringify(record);await reload();go(kind);message('İçerik arşivlendi.')});
$('history').onclick=()=>run(async()=>{const {versions}=await api('history',{id:record.id}),d=el('dialog');d.appendChild(el('h2','Önceki yayınlar'));for(const v of versions){const row=el('div',undefined,'item');row.append(el('span','Sürüm '+v.id+' · '+new Date(v.at).toLocaleString('tr-TR')));if(v.record)row.appendChild(button('Taslağa geri yükle',async()=>{if(!confirm('Seçilen sürüm taslağa alınsın mı? Canlı yayın ayrıca yapılır.'))return;await api('restore',{id:record.id,version:v.id,revision});baseline=JSON.stringify(record);await reload();open(items.find(x=>x.id===record.id));d.close();d.remove()}));d.appendChild(row)}if(!versions.length)d.appendChild(el('p','Henüz yayın geçmişi yok.'));d.appendChild(button('Kapat',()=>{d.close();d.remove()}));document.body.appendChild(d);d.showModal()});
$('seed').onclick=()=>run(async()=>{if(!confirm('Mevcut iki içerik taslak olarak içe alınsın mı? Var olan kimlikler atlanır; yayın ve kullanıcı kayıtları değişmez.'))return;for(const [file,next,source,cover]of [['the-mysterious-student','video','assets/story.mp4','assets/poster.jpg'],['every-day-every-way','song','assets/everyday-song.mp4','assets/everyday-poster.jpg']]){const payload=await(await fetch('../../data/'+file+'.json')).json();if(items.some(x=>x.id===payload.id))continue;const r={...newRecord(next),id:payload.id,title:payload.title,description:payload.description,source,cover,payload};await api('save',{record:r,revision:0})}await reload();message('Mevcut içerikler taslağa alındı. Canlı içerikler korundu.')});
$('seed').insertAdjacentElement('afterend',button('Yerel Studio içeriğini kurtar',async()=>{const found=[];for(const key of Object.keys(localStorage)){if(/^lingucat\.v[34]\..*(?:story|song)$/.test(key))try{const payload=E.validate(JSON.parse(localStorage.getItem(key)));found.push({...newRecord(key.endsWith('song')?'song':'video'),id:payload.id,title:payload.title,description:payload.description,payload})}catch{}}if(!found.length)throw Error('Bu tarayıcıda kayıtlı Studio içeriği bulunamadı. Eski JSON yedeğini içe aktarabilirsin.');const d=el('dialog');d.appendChild(el('h2','Bu tarayıcıdaki Studio içerikleri'));for(const value of found)d.appendChild(button(value.title,async()=>{const old=items.find(x=>x.id===value.id);if(!confirm('İçerik buluta taslak olarak kopyalansın mı? Mevcut yayın ve yerel kopya değişmez.'))return;await api('save',{record:value,revision:old?.revision||0});await reload();d.close();d.remove();message('Yerel içerik taslağa kopyalandı. Video URL’sini tamamlayabilirsin.')}));d.appendChild(button('Kapat',()=>{d.close();d.remove()}));document.body.appendChild(d);d.showModal()}));
$('popPreview').onclick=()=>{const win=window.open('../../index.html?lingu-preview='+previewToken,'_blank');if(!win){message('Önizleme penceresine izin ver.');return}const listener=e=>{if(e.source===win&&e.origin===location.origin&&e.data?.token===previewToken&&e.data?.type==='linguadmin:preview-ready'){win.postMessage({type:'linguadmin:preview',token:previewToken,...previewRecord()},location.origin);window.removeEventListener('message',listener)}};window.addEventListener('message',listener)};
for(const [id,icon,title,desc]of [['gameStudio','♧','Oyun Stüdyosu','Memory, Kelime Avı, Harf Dedektifi, Labirent ve ortak içerik paketleri.'],['create','＋','İçerik yükle','Şarkı, hikâye veya soru temelli oyun hazırla.'],['content','▤','İçerikler','Taslaklarını ve yayınlarını bul, düzenle.'],['media','▧','Medya kütüphanesi','İçeriklerinde tekrar kullanacağın dosyalar.'],['appearance','◈','Görünüm Düzenleyici','LinguCat’in öğrenci ekranını düzenle.']]){const b=button('',()=>go(id),'module');b.append(el('span',icon),el('b',title),el('small',desc));$('modules').appendChild(b)}
for(const [id,title]of [['home','Başlangıç'],['gameStudio','Oyun Stüdyosu'],['create','＋ İçerik yükle'],['content','İçerikler'],['media','Medya kütüphanesi'],['appearance','Görünüm Düzenleyici']]){const b=button(title,()=>go(id));b.dataset.kind=id;$('nav').appendChild(b)}
for(let i=1;i<=12;i++){const o=el('option',i+'. sınıf');o.value=i;$('gradeFilter').appendChild(o)}for(const id of ['search','statusFilter','gradeFilter','kindFilter'])$(id).addEventListener('input',renderList);
$('expandPreview').onclick=()=>{previewExpanded=!previewExpanded;document.querySelector('.preview').classList.toggle('preview-expanded',previewExpanded);$('expandPreview').textContent=previewExpanded?'Önizlemeyi küçült':'Önizlemeyi büyüt';resizePreview()};
for(const id of ['previewRole','previewGrade'])$(id).onchange=schedulePreview;
$('loginForm').onsubmit=e=>{e.preventDefault();run(async()=>{await persistentSession;if(persistenceError)throw Error('Kalıcı oturum kaydedilemiyor. Tarayıcı depolama izinlerini kontrol et.');await signInWithEmailAndPassword(auth,$('email').value,$('password').value)})};$('google').onclick=()=>run(async()=>{await persistentSession;if(persistenceError)throw Error('Kalıcı oturum kaydedilemiyor. Tarayıcı depolama izinlerini kontrol et.');await signInWithPopup(auth,new GoogleAuthProvider())});
async function preparePreview(){if(!('serviceWorker' in navigator))return;try{const registration=await navigator.serviceWorker.getRegistration(new URL('../../',location.href));if(!registration)return;await registration.update();const worker=registration.installing||registration.waiting;if(worker&&worker.state!=='activated')await new Promise(resolve=>{const timeout=setTimeout(resolve,15000);worker.addEventListener('statechange',()=>{if(['activated','redundant'].includes(worker.state)){clearTimeout(timeout);resolve()}})});}catch{}}
onAuthStateChanged(auth,async user=>{authorized=false;items=[];record=null;$('workspace').hidden=true;$('login').hidden=false;frame.src='about:blank';$('identity').textContent='';if(!user)return;try{const token=await getIdTokenResult(user,true);if(token.claims.admin!==true)throw Error('Bu hesap yönetici değil. LinguCat öğrenci/öğretmen hesabı LinguAdmin erişimi sağlamaz.');await api('session');authorized=true;$('identity').textContent=user.email;$('login').hidden=true;frameReady=false;await preparePreview();frame.src='../../index.html?lingu-preview='+previewToken;await reload();go('home');$('workspace').hidden=false;resizePreview()}catch(e){message(e.message)}});
window.addEventListener('beforeunload',e=>{if(dirty()){e.preventDefault();e.returnValue=''}});document.addEventListener('keydown',e=>{if(!authorized)return;if((e.ctrlKey||e.metaKey)&&e.key==='s'&&record){e.preventDefault();run(save)}if((e.ctrlKey||e.metaKey)&&e.shiftKey&&e.key.toLowerCase()==='z'&&record){e.preventDefault();$('undo').click()}});
